import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();

        int[] c = new int[2 * n + 1];
        c[n] = 1;
        for (int i = n - 1; i > 0; i--) {
            c[i] = (2 * c[i + 1]) % m;
            int limit = n / i;
            for (int j = 2; j <= limit; j++) {
                c[i] = (c[i] + c[i * j] - c[(i + 1) * j]) % m;
                if (c[i] < 0) c[i] += m; // handle negative modulus
            }
        }

        System.out.println((c[1] - c[2]) % m);
    }
}
